import json
import math
from pathlib import Path
from pyscipopt import Model, quicksum

data = json.loads(Path("/root/data.json").read_text())

vehicle_count = int(data["vehicle_count"])
vehicle_capacity = float(data["vehicle_capacity"])
penalty_weight = float(data["penalty_weight"])
depot = data["depot"]
stations_data = data["stations"]

n = len(stations_data)
station_ids = [int(s["id"]) for s in stations_data]
if len(station_ids) != len(set(station_ids)):
    raise ValueError("duplicate station ids")

id_to_idx = {sid: idx for idx, sid in enumerate(station_ids)}
idx_to_id = {idx: sid for sid, idx in id_to_idx.items()}

target = {idx: int(stations_data[idx]["net_rebalancing_target"]) for idx in range(n)}
initial_bikes = {idx: int(stations_data[idx]["initial_bikes"]) for idx in range(n)}
station_capacity = {idx: int(stations_data[idx]["station_capacity"]) for idx in range(n)}


def great_circle_miles(a, b, radius=3960.0):
    lat1 = float(a["latitude"])
    lon1 = float(a["longitude"])
    lat2 = float(b["latitude"])
    lon2 = float(b["longitude"])

    deg_to_rad = math.pi / 180.0
    phi1 = (90.0 - lat1) * deg_to_rad
    phi2 = (90.0 - lat2) * deg_to_rad
    theta1 = lon1 * deg_to_rad
    theta2 = lon2 * deg_to_rad

    cos_arc = (
        math.sin(phi1) * math.sin(phi2) * math.cos(theta1 - theta2)
        + math.cos(phi1) * math.cos(phi2)
    )
    cos_arc = max(-1.0, min(1.0, cos_arc))
    return math.acos(cos_arc) * radius


def node_loc(node):
    if node in (START, END):
        return depot
    return stations_data[node]


START = "depot_start"
END = "depot_end"
vehicles = range(vehicle_count)
stations = range(n)
from_nodes = [START, *stations]
to_nodes = [*stations, END]
arcs = [
    (i, j)
    for i in from_nodes
    for j in to_nodes
    if i != j and not (i == START and j == END)
]

dist = {}
for i, j in arcs:
    dist[i, j] = great_circle_miles(node_loc(i), node_loc(j))

model = Model("bike_rebalancing")
model.hideOutput()

# arc variables
x = {(v, i, j): model.addVar(vtype="B", name=f"x_{v}_{i}_{j}") for v in vehicles for i, j in arcs}

# route structure: start/end at depot exactly once, continuity, visit at most once
for v in vehicles:
    model.addCons(quicksum(x[v, START, j] for j in stations) == 1)
    model.addCons(quicksum(x[v, i, END] for i in stations) == 1)
    for i in stations:
        incoming = quicksum(x[v, j, i] for j in from_nodes if j != i)
        outgoing = quicksum(x[v, i, j] for j in to_nodes if j != i)
        model.addCons(incoming == outgoing)
        model.addCons(outgoing <= 1)

visit = {(v, i): quicksum(x[v, i, j] for j in to_nodes if j != i) for v in vehicles for i in stations}

# MTZ subtour elimination among stations
order = {
    (v, i): model.addVar(vtype="C", lb=1, ub=max(1, n), name=f"order_{v}_{i}")
    for v in vehicles
    for i in stations
}
for v in vehicles:
    for i in stations:
        for j in stations:
            if i != j and (i, j) in dist:
                model.addCons(order[v, i] - order[v, j] + n * x[v, i, j] <= n - 1)

# load / pickup / dropoff variables
start_load = {v: model.addVar(vtype="I", lb=0, ub=vehicle_capacity, name=f"start_load_{v}") for v in vehicles}
end_load = {v: model.addVar(vtype="I", lb=0, ub=vehicle_capacity, name=f"end_load_{v}") for v in vehicles}
load_after = {
    (v, i): model.addVar(vtype="I", lb=0, ub=vehicle_capacity, name=f"load_{v}_{i}")
    for v in vehicles
    for i in stations
}
pick = {
    (v, i): model.addVar(vtype="I", lb=0, ub=vehicle_capacity, name=f"pick_{v}_{i}")
    for v in vehicles
    for i in stations
}
drop = {
    (v, i): model.addVar(vtype="I", lb=0, ub=vehicle_capacity, name=f"drop_{v}_{i}")
    for v in vehicles
    for i in stations
}
mode = {(v, i): model.addVar(vtype="B", name=f"mode_{v}_{i}") for v in vehicles for i in stations}

M = vehicle_capacity

for v in vehicles:
    for i in stations:
        model.addCons(pick[v, i] <= vehicle_capacity * visit[v, i])
        model.addCons(drop[v, i] <= vehicle_capacity * visit[v, i])
        model.addCons(pick[v, i] <= vehicle_capacity * mode[v, i])
        model.addCons(drop[v, i] <= vehicle_capacity * (1 - mode[v, i]))

    # load propagation along selected arcs
    for i, j in arcs:
        if j in stations:
            prev_load = start_load[v] if i == START else load_after[v, i]
            net_j = pick[v, j] - drop[v, j]
            model.addCons(load_after[v, j] - prev_load - net_j <= M * (1 - x[v, i, j]))
            model.addCons(load_after[v, j] - prev_load - net_j >= -M * (1 - x[v, i, j]))
        elif j == END:
            prev_load = start_load[v] if i == START else load_after[v, i]
            model.addCons(end_load[v] - prev_load <= M * (1 - x[v, i, j]))
            model.addCons(end_load[v] - prev_load >= -M * (1 - x[v, i, j]))

# station-level aggregation and constraints
total_picked = {i: quicksum(pick[v, i] for v in vehicles) for i in stations}
total_dropped = {i: quicksum(drop[v, i] for v in vehicles) for i in stations}
net_change = {i: total_picked[i] - total_dropped[i] for i in stations}

for i in stations:
    final_inv_expr = initial_bikes[i] - total_picked[i] + total_dropped[i]
    model.addCons(final_inv_expr >= 0)
    model.addCons(final_inv_expr <= station_capacity[i])

dev = {i: model.addVar(vtype="I", lb=0, name=f"dev_{i}") for i in stations}
for i in stations:
    model.addCons(net_change[i] - target[i] <= dev[i])
    model.addCons(target[i] - net_change[i] <= dev[i])

travel_cost = quicksum(dist[i, j] * x[v, i, j] for v in vehicles for i, j in arcs)
penalty_cost = penalty_weight * quicksum(dev[i] for i in stations)

model.setObjective(travel_cost + penalty_cost, "minimize")

model.setParam("limits/time", 300.0)
model.setParam("limits/gap", 0.0)

model.optimize()

status = str(model.getStatus()).lower()
if model.getNSols() == 0:
    raise RuntimeError(f"SCIP found no feasible solution; status={status}")

print("status:", status)
print("objective:", model.getObjVal())

# extract solution
sol = {}
sol["status"] = status
sol["objective"] = model.getObjVal()

vehicles_out = []
for v in vehicles:
    # build route by following arcs
    outgoing = {}
    for i, j in arcs:
        if model.getVal(x[v, i, j]) > 0.5:
            outgoing[i] = j
    route = [START]
    cur = START
    seen = {START}
    while cur != END:
        if cur not in outgoing:
            raise RuntimeError(f"route disconnected at {cur!r} for vehicle {v}")
        nxt = outgoing[cur]
        if nxt in seen and nxt != END:
            raise RuntimeError(f"cycle detected at {nxt!r} for vehicle {v}")
        route.append(nxt)
        seen.add(nxt)
        cur = nxt

    stops = []
    for node in route[1:-1]:
        i = node
        p = model.getVal(pick[v, i])
        d = model.getVal(drop[v, i])
        la = model.getVal(load_after[v, i])
        stops.append({
            "station_id": idx_to_id[i],
            "bikes_picked_up": round(p),
            "bikes_dropped_off": round(d),
            "load_after_stop": round(la),
        })

    vehicles_out.append({
        "vehicle_id": v + 1,
        "start_load": round(model.getVal(start_load[v])),
        "route": [START] + [idx_to_id[node] for node in route[1:-1]] + [END],
        "stops": stops,
        "end_load": round(model.getVal(end_load[v])),
    })

stations_out = []
for i in stations:
    tp = sum(model.getVal(pick[v, i]) for v in vehicles)
    td = sum(model.getVal(drop[v, i]) for v in vehicles)
    nc = tp - td
    unmet = model.getVal(dev[i])
    stations_out.append({
        "station_id": idx_to_id[i],
        "net_rebalancing_target": target[i],
        "total_bikes_picked_up": round(tp),
        "total_bikes_dropped_off": round(td),
        "net_bike_change": round(nc),
        "unmet_rebalancing_amount": round(unmet),
    })

travel_distance = 0.0
for v in vehicles:
    r = vehicles_out[v]["route"]
    internal = [START] + [id_to_idx[node] for node in r[1:-1]] + [END]
    for a, b in zip(internal, internal[1:]):
        travel_distance += dist[a, b]

total_unmet = sum(s["unmet_rebalancing_amount"] for s in stations_out)
unmet_penalty = penalty_weight * total_unmet
objective = travel_distance + unmet_penalty

report = {
    "summary": {
        "objective": objective,
        "travel_distance_miles": travel_distance,
        "unmet_rebalancing_penalty": unmet_penalty,
        "total_unmet_rebalancing_amount": total_unmet,
    },
    "vehicles": vehicles_out,
    "stations": stations_out,
}

Path("/root/work/report_raw.json").write_text(json.dumps(report, indent=2))
print("wrote report_raw.json")
print(json.dumps(report["summary"], indent=2))

print("status:", status)
print("objective:", model.getObjVal())
try:
    print("gap:", model.getGap())
    print("dual bound:", model.getDualbound())
except Exception as e:
    print("gap query failed:", e)

# extract solution
sol = {}
